Matching Ayahs
- = Alif, Lām, Mīm. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Ceux-là sont sur le droit chemin de leur Seigneur, et ce sont eux qui réussissent. 2:5; 31:5
- = Ô Enfants d'Israël, rappelez-vous Mon bienfait dont Je vous ai comblés, et que Je vous ai préférés aux mondes (aux peuples). 2:47; 2:122
- = Cette communauté est bien révolue. Elle recevra ce qu'elle a mérité, et vous recevrez ce que vous avez mérité. Et vous ne serez pas interrogés sur ce qu'ils faisaient. 2:134; 2:141
- = Ils y demeureront éternellement. Le châtiment ne leur sera pas allégé, et ils n'auront aucun répit. 2:162; 3:88
- = Excepté ceux qui, après cela, se repentent et se réforment. Car Allah est Pardonneur et Miséricordieux. 3:89; 24:5
- = Mais ceux qui ont mécru et ont traité Nos signes de mensonge – ceux-là sont les gens de la Fournaise. 5:10; 5:86
- = Et il ne leur vient aucun signe parmi les signes de leur Seigneur, sans qu'ils ne s'en détournent. 6:4; 36:46
- = Et avant toi, des Messagers ont été raillés ; mais ceux qui se moquaient furent cernés par cela même dont ils se moquaient. 6:10; 21:41
- = Dis : "Je crains, si je désobéis à mon Seigneur, le châtiment d'un jour terrible." 6:15; 39:13
- = Alors le tremblement de terre les saisit, et ils gisaient dans leurs demeures, tombés sur le visage. 7:78; 7:91
- = Il jeta son bâton, et le voici devenu un serpent manifeste. 7:107; 26:32
- = Et il sortit sa main, et la voici blanche (éclatante) pour ceux qui regardaient. 7:108; 26:33
- = Ils dirent : "Nous croyons au Seigneur de l'univers." 7:121; 26:47
- = Le Seigneur de Moïse et d'Aaron. 7:122; 26:48
- = Et Je leur donnerai du répit. Car Mon stratagème est solide. 7:183; 68:45
- = C'est Lui qui a envoyé Son Messager avec la bonne direction et la religion de la vérité, afin qu'elle triomphe sur toute autre religion, même si les associateurs en ont horreur. 9:33; 61:9
- = Ô Prophète, lutte contre les mécréants et les hypocrites, et sois rude avec eux. Leur refuge est l'Enfer, et quelle mauvaise destination ! 9:73; 66:9
- = Et ils disent : "À quand cette promesse, si vous êtes véridiques ?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Et Nous avons envoyé Moïse avec Nos signes et une autorité évidente. 11:96; 40:23
- = Et Nous avons donné à Moïse le Livre, mais on divergea à son sujet. Et n'eût été une parole préalable de ton Seigneur, il aurait été jugé entre eux. Et ils sont, à son sujet, dans un doute troublant. 11:110; 41:45
- = Cela n'est pas difficile pour Allah. 14:20; 35:17
- = "Et quand Je l'aurai bien formé et lui aurai insufflé de Mon Esprit, jetez-vous devant lui en prosternation." 15:29; 38:72
- = Alors les Anges se prosternèrent tous ensemble. 15:30; 38:73
- = (Allah) dit : "Sors d'ici, car te voilà banni." 15:34; 38:77
- = (Iblîs) dit : "Seigneur, donne-moi donc un répit jusqu'au jour où ils seront ressuscités." 15:36; 38:79
- = (Allah) dit : "Tu es donc de ceux à qui répit est accordé." 15:37; 38:80
