- La nuit, pour que vous vous y reposiez, et le jour, pour que vous voyiez; en vérité, il y a là des signes pour des gens qui réfléchissent. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- Et ce qui t'a été révélé de ton Seigneur ne fera qu'accroître chez beaucoup d'entre eux la rébellion et la mécréance. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
