- Et ils disent: "Pourquoi n'a-t-on pas fait descendre sur lui un signe de son Seigneur?" Dis: "En vérité." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- Avant que vienne un jour qui n'a pas de retour de la part d'Allah. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- C'est là la grâce d'Allah qu'Il donne à qui Il veut, et Allah est le Détenteur de la grâce immense. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
