- Que cela est la vérité venant de leur Seigneur, et qu'Allah n'est pas inattentif à ce qu'ils font. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- Devant eux et derrière eux, afin que vous n'adoriez personne en dehors d'Allah. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- En vérité, vous recherchez les hommes avec passion au lieu des femmes; vous êtes un peuple outrancier. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
