- Ceux qui sont dans les cieux et ceux qui sont sur la terre, sauf ceux qu'Allah veut. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
