- Et Il fit descendre du ciel une eau, et par elle, Il fit sortir des fruits comme subsistance pour vous. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- Et lorsque Nous avons pris votre engagement et élevé au-dessus de vous le Mont Tur: "Prenez ce que Nous vous avons donné avec force." (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
- Et il se détourna d'eux et dit: "Ô mon peuple! Je vous ai bien transmis le message de mon Seigneur et je vous ai conseillés." (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
- Des rivières coulent sous eux, ils seront parés de bracelets d'or. (تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ) 18:31; 22:23
