- Il t'est venu de la science, tu n'as d'Allah ni protecteur ni. (جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا) 2:120; 13:37
- Et quand Nous accordons une faveur à l'homme, il se détourne et s'éloigne, et quand le mal le touche. (وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَى بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ) 17:83; 41:51
- Et rien de plus petit ou de plus grand que cela, qui ne soit dans un Livre explicite. (وَلَا أَصْغَرَ مِن ذَلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ مُّبِينٍ) 10:61; 34:3

