- Je leur pardonnerai leurs péchés et les ferai entrer dans des jardins sous lesquels coulent les rivières. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- Nous les ferons entrer dans des jardins sous lesquels coulent les rivières, où ils demeureront éternellement. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- Ton Seigneur sait mieux qui s'égare de Son chemin, et Il sait mieux. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- Vous serez ramenés à Celui qui connaît l'invisible et le visible, et Il vous informera de ce que vous faisiez. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- Ils tuaient vos fils et laissaient vivre vos femmes; il y avait là une grande épreuve de la part de votre Seigneur. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- En vérité, ton Seigneur sait mieux qui s'égare de Son chemin, et Il. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- Allah, à Qui appartient ce qui est dans les cieux et ce qui est sur la terre. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- Parmi les communautés qui ont vécu avant vous, parmi les djinns et les hommes. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- Adorez Allah, vous n'avez pas d'autre divinité que Lui, ne craindrez-vous donc pas? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- Et Nous avons mis des voiles sur leurs cœurs, afin qu'ils ne le comprennent pas, et dans leurs oreilles une lourdeur. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- Il jugera entre eux au Jour de la Résurrection sur ce en quoi ils divergeaient. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- Il dit: "Ô mon peuple! Que pensez-vous si je suis sur une preuve évidente de mon Seigneur?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- Cela, pour ce que vos mains ont commis, et Allah n'est point injuste envers les serviteurs. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- Pour eux, il y aura ignominie dans ce monde, et un grand châtiment dans l'au-delà. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- Ce qui est dans les cieux et ce qui est sur la terre, et Allah suffit comme Protecteur. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- Sauf ceux qui ont cru et ont fait de bonnes œuvres; pour eux, une récompense qui ne sera jamais interrompue. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- Pour que tu ne Me donnes pas d'associés, ce dont tu n'as aucune connaissance; ne leur obéis donc pas. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- En vérité, ceci est un rappel; que celui qui veut prenne un chemin vers son Seigneur. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- Et quiconque est reconnaissant, c'est pour son propre bien qu'il l'est; et quiconque est ingrat. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- Ceux qui accomplissent la prière, donnent la zakât et qui croient fermement en l'au-delà. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- À Abraham, Ismaël, Isaac, Jacob et les tribus, et ce qui a été donné à Moïse et à Jésus. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- Par groupes, jusqu'à ce qu'ils y parviennent, ses portes s'ouvrent et ses gardiens leur disent. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- Allah ne vous tient pas rigueur des serments involontaires, mais Il vous tient rigueur de ce que. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- Une miséricorde, ils s'en réjouissent; et si un malheur les atteint à cause de ce que leurs mains ont commis. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- Des jardins sous lesquels coulent les rivières, où ils demeureront éternellement, et quelle belle récompense pour ceux qui œuvrent! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- Allah sait ce qui est dans les cieux et ce qui est sur la terre, et Allah. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- Obéissez à Allah et obéissez au Messager; mais si vous vous détournez, il lui incombe. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- Ils ont leur récompense auprès de leur Seigneur, et il n'y a pas de crainte sur eux, et ils. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- Et ils dirent: "Quand nous serons ossements et poussière, serons-nous vraiment ressuscités en une nouvelle création?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- Et ils ne trouveront pour eux, en dehors d'Allah, ni protecteur ni secoureur. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "Combien de temps es-tu resté?" Il dit: "Je suis resté un jour ou une partie d'un jour." Il dit. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- Jusqu'au Jour de la Résurrection, quel est le dieu autre qu'Allah qui pourrait vous l'apporter? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- Quiconque fait le bien, homme ou femme, et qu'il est croyant. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- Ceux qui détournent du chemin d'Allah et qui cherchent à le rendre tortueux, et qui ne croient pas en l'au-delà. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- Mangez où vous voulez, mais n'approchez pas cet arbre, sinon vous serez parmi les injustes. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- Dis: "Ô mon peuple! Agissez selon votre position, moi aussi j'agis, et vous saurez bientôt." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- En vérité, les perdants sont ceux qui ont perdu eux-mêmes et leurs familles au Jour de la Résurrection, n'est-ce pas. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- Quiconque se guide, c'est pour son propre bien; et quiconque s'égare, c'est à son propre détriment; et. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- Et ceux qui ont mécru disent: "Pourquoi n'a-t-on pas fait descendre sur lui un signe de son Seigneur?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- Celui qui vous a fait la nuit pour que vous vous y reposiez, et le jour pour que vous voyiez, en vérité. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- Avant que vienne un jour où il n'y aura ni rachat, ni amitié. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- Afin qu'ils réfléchissent que leur compagnon n'est pas possédé; il n'est qu'un avertisseur. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- Ils y demeureront éternellement; le châtiment ne leur sera pas allégé et ils n'auront pas de répit. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- Ne tends pas tes yeux vers ce dont Nous avons donné la jouissance à certains d'entre eux. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- Ne trompez pas les gens sur leurs biens, et ne commettez pas de désordre sur la terre. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- Et la paix soit sur lui le jour où il naquit, le jour où il mourra, et le jour où il sera ressuscité vivant. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- Ô mon peuple! Agissez selon votre position, moi aussi j'agis, et vous saurez bientôt qui. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- Et il n'appartient pas à un Messager d'apporter un signe sans la permission d'Allah. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- Ensuite, chaque âme sera pleinement récompensée pour ce qu'elle aura acquis, et ils ne seront pas lésés. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- Homme ou femme, et qu'il est croyant, ceux-là entreront au Paradis. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- Il ne S'est point octroyé d'enfant et il n'a point d'associé dans la royauté. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- Et celui qu'Allah guide, il est bien guidé; et celui qu'Il égare, tu ne lui trouveras. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- Regarde comment ils te proposent des paraboles, ils se sont égarés et ne peuvent trouver le chemin. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- Dis: "Je crains, si je désobéis à mon Seigneur, le châtiment d'un jour terrible." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- Leur nudité leur apparut, et ils se mirent à se couvrir avec des feuilles du Paradis. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- Et invoquez ceux que vous pouvez, en dehors d'Allah, si vous êtes sincères. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- Tout ce qui est sur la terre et autant encore, pour s'en racheter. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- Prenez ce que Nous vous avons donné avec force, et souvenez-vous de ce qui s'y trouve, afin que vous deveniez pieux. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- Commettez-vous l'abomination qu'aucun être humain avant vous n'a commise? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- Et à Allah appartient ce qui est dans les cieux et ce qui est sur la terre, et Allah est. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- Les méfaits qu'ils ont commis les ont atteints, et ce dont ils se moquaient les a enveloppés. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- Un Messager de parmi vous, qui vous récite Nos versets, vous purifie et vous enseigne le Livre et la Sagesse. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- Il en jaillit douze sources; chaque groupe connaissait son point d'eau. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- Seulement une conjecture, et la conjecture ne sert de rien contre la vérité. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- Lorsque Je l'aurai achevé et lui aurai insufflé de Mon Esprit, jetez-vous devant lui en prosternation. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- À qui appartient la bonne fin de la demeure? En vérité, les injustes ne réussiront pas. (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
